class LinkedQueue {
  constructor() {
    this.tail = null;                // the back; tail.next is the front
    this.count = 0;
  }
  enqueue(x) {
    const node = new ListNode(x);
    if (this.tail === null) {
      node.next = node;              // one node: it is its own next
    } else {
      node.next = this.tail.next;    // the new node points at the front...
      this.tail.next = node;         // ...and the old back points at it
    }
    this.tail = node;                // it becomes the back
    this.count++;
  }
  dequeue() {
    if (this.tail === null) return -1;
    const first = this.tail.next;
    if (first === this.tail) this.tail = null;   // the last node leaves
    else this.tail.next = first.next;           // skip over the old front
    this.count--;
    return first.val;
  }
  front() {
    return this.tail === null ? -1 : this.tail.next.val;
  }
  isEmpty() {
    return this.count === 0;
  }
  size() {
    return this.count;
  }
}

